sys_hub_input_scripts.script:
{"json_draft":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/

var selectedReport =fd_data.trigger.current.variables.ohsm_repo_report.toString();
var selectedYear = fd_data.trigger.current.variables.ohsm_repo_year.toString();

var resObj= new HoCOHSMRepo();
return resObj.getReportByTypeandYear(selectedReport,selectedYear);","savedValue":""}}

